import { ReactComponent as AddSVG } from '@/assets/common/add.svg';
import { ReactComponent as HistorySVG } from '@/assets/common/history.svg';
import { history } from '@umijs/max';
import { Button, Tooltip } from 'antd';
import emitter from '../eventBus';

const Operation: React.FC = () => {
  const onClearClick = async () => emitter.emit('clear');

  const onHistoryClick = () => {
    history.push('/newHistory');
  };

  return (
    <>
      <Tooltip placement="left" title="新建会话">
        <Button
          type="link"
          onClick={onClearClick}
          icon={<AddSVG />}
          style={{ width: 25 }}
        />
      </Tooltip>
      <Tooltip placement="left" title="查看历史记录">
        <Button
          type="link"
          onClick={onHistoryClick}
          icon={<HistorySVG />}
          style={{ width: 25 }}
        />
      </Tooltip>
    </>
  );
};
export default Operation;
