import { useGlobalStore } from '@/store';
import { Outlet, history, useLocation } from '@umijs/max';
import { Tabs, TabsProps } from 'antd';
import { FC, useEffect, useState } from 'react';
import Operation from '../Agentic/Operation';
import ChatOperation from '../Chat/Operation';
import styles from './index.module.less';

const items: TabsProps['items'] = [
  {
    key: `chat`,
    label: 'Chat',
  },
];

const Main: FC = () => {
  const [currentTab, setCurrentTab] = useState<string>('chat');
  const { pluginConfig } = useGlobalStore();

  const { mode } = pluginConfig;

  const location = useLocation();

  useEffect(() => {
    if (location.pathname === '/') {
      const targetPath = mode === 'chat' || !mode ? '/oldChat' : '/chat';
      console.log(`Redirecting to ${targetPath} based on mode: ${mode}`);
      history.replace(targetPath);
    }
  }, [location.pathname, mode]);

  const changeTabAndRoute = (key: string, state?: any) => {
    console.log('tab切换路由切换：', { key, state });
    // 由于 Chat 的特殊性，其有两种模式，因此在这里做一下转换
    setCurrentTab(key === 'oldChat' ? 'chat' : key);
    history.push(
      {
        pathname: `/${key}`,
      },
      state,
    );
  };

  useEffect(() => {
    // 解析当前的 pathname
    const pathSegments = location.pathname.split('/').filter(Boolean);
    const rootPath = pathSegments[0]; // 获取路径的第一部分

    // 检查是否有匹配的 tab key
    const matchingTab = items.find(
      (item) => item.key.split('/')[0] === rootPath,
    );
    if (matchingTab && matchingTab.key !== currentTab) {
      setCurrentTab(matchingTab.key);
    }
  }, [location]);

  const onClickTab = (key: string) => {
    const isChatTab = key === 'chat';
    const routeKey = isChatTab && mode !== 'agent' ? 'oldChat' : key;
    changeTabAndRoute(routeKey);
  };

  return (
    <div className={styles.home}>
      <Tabs
        size="small"
        onChange={onClickTab}
        items={items}
        activeKey={currentTab}
        tabBarExtraContent={
          <>
            {currentTab === 'chat' && mode === 'agent' && <Operation />}
            {currentTab === 'chat' && mode !== 'agent' && <ChatOperation />}
          </>
        }
      />
      <Outlet />
    </div>
  );
};
export default Main;
