import { ReactComponent as AddSVG } from '@/assets/common/add.svg';
import { ReactComponent as HistorySVG } from '@/assets/common/history.svg';
import { history } from '@umijs/max';
import { Button, Tooltip } from 'antd';
import { FC } from 'react';
import { useChatList } from '../hooks/useChatList';

const Operation: FC = () => {
  const { onCreateNewChat } = useChatList();

  const onNewChatClick = () => {
    onCreateNewChat();
  };

  const onHistoryClick = () => {
    history.push('/newHistory');
  };

  return (
    <>
      <Tooltip placement="top" title="新建会话">
        <Button
          type="link"
          onClick={onNewChatClick}
          icon={<AddSVG />}
          style={{ width: 25 }}
        />
      </Tooltip>
      <Tooltip placement="topLeft" title="查看历史">
        <Button
          type="link"
          onClick={onHistoryClick}
          icon={<HistorySVG />}
          style={{ width: 25 }}
        />
      </Tooltip>
    </>
  );
};

export default Operation;
