import { getSessionId } from '@/services/Api/agentic';
import { useChatStore, useGlobalStore } from '@/store';
import { throttle } from 'lodash';
import { useCallback } from 'react';

export interface ChatListItem {
  chatId: string;
  chatType: 'new' | 'history';
  openTime: number;
}

export const useChatList = () => {
  const { chatList, setChatList, setChatMessageList } = useChatStore();
  const {
    projectConfig: { sideCarIDEInfo },
  } = useGlobalStore();

  const onCreateNewChat = useCallback(
    throttle(async () => {
      if (!sideCarIDEInfo) {
        return;
      }
      const { sideCarPort } = sideCarIDEInfo;

      // 清空当前会话的消息数据（如果有的话）
      if (chatList.length > 0) {
        chatList.forEach((chat) => {
          setChatMessageList(chat.chatId, []);
        });
      }

      const res = await getSessionId(`http://localhost:${sideCarPort}`);
      if (res.success) {
        // 创建新的会话，替换当前会话
        const newChatItem: ChatListItem = {
          // @ts-ignore
          chatId: res.session_id,
          chatType: 'new',
          openTime: new Date().getTime(),
        };
        setChatList([newChatItem]);

        // 确保新会话的消息列表为空
        // @ts-ignore
        setChatMessageList(res.session_id, []);
      }
    }, 300),
    [chatList, setChatList, setChatMessageList, sideCarIDEInfo],
  );

  const onChangeChat = useCallback(
    throttle(async () => {
      // 清空当前会话等同于新建会话
      await onCreateNewChat();
    }, 300),
    [onCreateNewChat],
  );

  return {
    chatList,
    onCreateNewChat,
    onChangeChat,
  };
};
